select.if:
SELECT DISTINCT a.power_type, b.*, d.`name` user_name, e.`name` duty_name , c.`name` project_name, c.id 'project.id', c.name 'project.name', c.short_name 'project.short_name', c.serial_number 'project.serial_number', pl.`name` monomer_name, area.`name` areaName, mbf.`name` factory_name, mbw.`name` workshop_name, mbpl.`name` production_line_name, mbp.`name` processName FROM mes_building_qhse_user_link a INNER JOIN mes_building_qhse b ON a.qhse_id = b.id AND b.bool_delete_enum=FALSE LEFT JOIN sys_user d ON b.user_id =d.id AND d.bool_delete_enum=FALSE LEFT JOIN sys_user e ON b.duty_id =e.id AND e.bool_delete_enum=FALSE LEFT JOIN mes_building_qhse_rectify rectify ON rectify.qhse_id=b.id and rectify.bool_delete_enum=FALSE LEFT JOIN sys_user u ON u.id=rectify.user_id and u.bool_delete_enum=FALSE LEFT JOIN contract_project c ON b.project_id = c.id AND c.bool_delete_enum=FALSE LEFT JOIN plan_monomer pl ON b.monomer_id = pl.id AND pl.bool_delete_enum=FALSE LEFT JOIN plan_area area ON b.area_id=area.id AND area.bool_delete_enum=FALSE LEFT JOIN mes_building_factory mbf ON b.factory_id=mbf.id AND mbf.bool_delete_enum=FALSE LEFT JOIN mes_building_workshop mbw ON b.workshop_id= mbw.id AND mbw.bool_delete_enum=FALSE LEFT JOIN mes_building_production_line mbpl ON b.production_line_id=mbpl.id AND mbpl.bool_delete_enum=FALSE LEFT JOIN mes_building_process mbp ON b.process_id=mbp.id AND mbp.bool_delete_enum=FALSE WHERE a.bool_delete_enum=FALSE
and b.id = #{qhseId}
and b.id in
#{qhseId}
and a.user_id=#{userId}
AND b.project_id = #{projectId}
AND d.name LIKE CONCAT('%', #{userName},'%')
AND e.name LIKE CONCAT('%', #{dutyName},'%')
AND u.name LIKE CONCAT('%', #{rectifyName},'%')
AND b.type & #{type}
AND b.status = #{status}
AND b.status != #{noStatus}
AND date(b.create_time)>=date(#{startDate})
AND date(b.create_time) <= date(#{endDate})
AND date_format(b.create_time,'%Y%m%d') = date_format(#{specifiedDate},'%Y%m%d')
and b.process_id = #{processId}
and b.level_one_type = #{levelOneType}
and b.level_two_type = #{levelTwoType}
order by b.status , b.create_time desc

SELECT DISTINCT b.*, d.`name` user_name, e.`name` duty_name , c.`name` project_name, c.id 'project.id', c.name 'project.name', c.short_name 'project.short_name', c.serial_number 'project.serial_number', pl.`name` monomer_name, area.`name` areaName, mbf.`name` factory_name, mbw.`name` workshop_name, mbpl.`name` production_line_name, mbp.`name` processName FROM mes_building_qhse b LEFT JOIN sys_user d ON b.user_id =d.id AND d.bool_delete_enum=FALSE LEFT JOIN sys_user e ON b.duty_id =e.id AND e.bool_delete_enum=FALSE LEFT JOIN mes_building_qhse_rectify rectify ON rectify.qhse_id=b.id and rectify.bool_delete_enum=FALSE LEFT JOIN sys_user u ON u.id=rectify.user_id and u.bool_delete_enum=FALSE LEFT JOIN contract_project c ON b.project_id = c.id AND c.bool_delete_enum=FALSE LEFT JOIN plan_monomer pl ON b.monomer_id = pl.id AND pl.bool_delete_enum=FALSE LEFT JOIN plan_area area ON b.area_id=area.id AND area.bool_delete_enum=FALSE LEFT JOIN mes_building_factory mbf ON b.factory_id=mbf.id AND mbf.bool_delete_enum=FALSE LEFT JOIN mes_building_workshop mbw ON b.workshop_id= mbw.id AND mbw.bool_delete_enum=FALSE LEFT JOIN mes_building_production_line mbpl ON b.production_line_id=mbpl.id AND mbpl.bool_delete_enum=FALSE LEFT JOIN mes_building_process mbp ON b.process_id=mbp.id AND mbp.bool_delete_enum=FALSE
LEFT JOIN tech_artifact ta ON b.product_id = ta.id and b.task_type_enum = 2
WHERE b.bool_delete_enum=FALSE
and b.id = #{qhseId}
and b.id in
#{qhseId}
AND b.project_id = #{projectId}
AND d.name LIKE CONCAT('%', #{userName},'%')
AND e.name LIKE CONCAT('%', #{dutyName},'%')
AND u.name LIKE CONCAT('%', #{rectifyName},'%')
AND ta.serial_number LIKE CONCAT('%', #{serialNumber},'%')
AND b.type & #{type}
AND b.status = #{status}
AND b.status != #{noStatus}
AND date(b.create_time)>=date(#{startDate})
AND date(b.create_time) <= date(#{endDate})
AND date_format(b.create_time,'%Y-%m-%d') = date_format(#{specifiedDate},'%Y-%m-%d')
and b.process_id = #{processId}
and b.level_one_type = #{levelOneType}
and b.level_two_type = #{levelTwoType}

mapper.select:
select DATE_FORMAT(create_time, '%c') month, count(*) quantity
from mes_building_qhse
where date_format(create_time, '%Y') = #{year}
  and bool_delete_enum = 0
  and type = #{type}
group by DATE_FORMAT(create_time, '%c')

SELECT DATE_FORMAT(create_time, '%Y-%m') month,
       COUNT(*) quantity
FROM mes_building_qhse
WHERE type & #{type}
  AND bool_delete_enum = FALSE
  AND DATE_FORMAT(create_time
    , '%Y')= DATE_FORMAT(#{dateTime}
    , '%Y')

    AND workshop_id =#{workShopId}

GROUP BY DATE_FORMAT(create_time, '%Y-%m')

SELECT *
FROM mes_building_qhse
WHERE bool_delete_enum = 0

    AND type & #{type}


    AND date_format (create_time, '%Y')= date_format(#{time}, '%Y')


    AND workshop_id = #{workShopId}

select * from
mes_building_qhse qhse
    left join mes_building_team_user_link link on qhse.team_id = link.team_id
where link.user_id = #{userId}
and qhse.bool_delete_enum = 0
and type = 1
and process_id = #{processId}
and DATE_FORMAT(qhse.create_time,'%Y') = #{year}

SELECT art.serial_number, qhse.number FROM mes_building_warehouse_summary sum left join mes_building_warehouse_record rec on sum.product_id = rec.product_id and sum.product_type = rec.product_type INNER JOIN mes_building_qhse qhse on rec.product_id = qhse.product_id and rec.number = qhse.number and rec.product_type = 2 left join tech_artifact art on qhse.product_id = art.id and art.bool_delete_enum = 0 where rec.bool_delete_enum = 0 and qhse.bool_delete_enum = 0 AND rec.type = 1 AND rec.`status` = 1 and qhse.type = 8 and qhse.`status` = 1 and(
( sum.id = #{key} and qhse.number in
#{number}
)
)

select qhse.qhse_number, cp.serial_number projectSerialNumber, cp.short_name projectShortName, case when qhse.task_type_enum = 2 then ta.serial_number when qhse.task_type_enum = 16 then ass.serial_number end as serial_number, su.`name` inspectionName, qhse.create_time inspectionDate, su2.`user_name` teamLeaderName, pro.`name` processName, mqone.NAME levelOneName, mqtwo.NAME levelTwoName, mqtwo.behavior_score behaviorScore, mqtwo.penalty penalty, qhse.status from mes_building_qhse qhse left join contract_project cp on qhse.project_id = cp.id and cp.bool_delete_enum = 0 left join tech_artifact ta on qhse.product_id = ta.id and ta.bool_delete_enum = 0 and qhse.task_type_enum = 2 left join tech_assemble ass on qhse.product_id = ass.id and ass.bool_delete_enum = 0 and qhse.task_type_enum = 16 left join sys_user su on qhse.user_id = su.id and su.bool_delete_enum = 0 left join mes_building_team_user_link su2 on qhse.team_id = su2.team_id and su2.bool_delete_enum = 0 and su2.bool_leader_enum = 1 LEFT JOIN mes_quality_class_config mqone ON mqone.id = qhse.level_one_type AND mqone.bool_delete_enum = 0 LEFT JOIN mes_quality_class_config mqtwo ON mqtwo.id = qhse.level_two_type AND mqtwo.bool_delete_enum = 0 left join mes_building_process pro on qhse.process_id = pro.id and pro.bool_delete_enum = 0 where qhse.type IN (1, 8)
AND date(qhse.create_time) >= date(#{startDate})
AND date(qhse.create_time) <= date(#{endDate})
and qhse.status = #{status}
and qhse.process_id = #{processId}
and qhse.level_one_type = #{levelOneType}
and cp.name like concat('%',#{projectName},'%')
and (ta.serial_number like concat('%',#{serialNumber},'%') or ass.serial_number like concat('%',#{serialNumber},'%'))
and su.name = #{inspectionUserName}
and su.name = #{teamLeaderName}

SELECT cp.`short_name` 'project.shortName', cp.serial_number 'project.serialNumber', shop.`name` 'workshop.name', pss.`name` 'processName', qhse.monomer_id, qhse.product_id, qhse.task_type_enum, CASE qhse.task_type_enum WHEN 2 THEN art.serial_number WHEN 16 THEN ass.serial_number END serialNumber, tulink.user_name 'team.name', qhse.id, qhse.`status`, su.id 'inspectUserId', su.name 'name', qhse.create_time, qhse.number FROM mes_building_qhse qhse left join contract_project cp on qhse.project_id = cp.id and cp.bool_delete_enum = 0 left join mes_building_workshop shop on qhse.workshop_id = shop.id and shop.bool_delete_enum = 0 left join mes_building_process pss on qhse.process_id = pss.id and pss.bool_delete_enum = 0 left join tech_artifact art on qhse.product_id = art.id and art.bool_delete_enum = 0 left join tech_assemble ass on qhse.product_id = ass.id and ass.bool_delete_enum = 0 left join mes_building_team_user_link tulink on qhse.team_id = tulink.team_id and tulink.bool_delete_enum = 0 and tulink.bool_leader_enum = 1 left join sys_user su on qhse.user_id = su.id and su.bool_delete_enum = 0 where qhse.bool_delete_enum = 0 and qhse.type in (1,8)
and
qhse.team_id in
#{team.id}
and (art.structure_class_id in
#{classId}
or ass.assemble_config_id in
#{classId}
)
and qhse.create_time >= #{startDate}
and qhse.create_time <= #{endDate}
and qhse.project_id = #{projectId}
and shop.id = #{workShopId}
and art.serial_number like concat('%',#{serialNumber},'%') or ass.serial_number like concat('%',#{serialNumber},'%')

SELECT cp.`short_name` 'project.shortName', cp.serial_number 'project.serialNumber', shop.`name` 'workshop.name', pss.`name` 'processName', qhse.monomer_id, qhse.product_id, qhse.task_type_enum, CASE qhse.task_type_enum WHEN 2 THEN art.serial_number WHEN 16 THEN ass.serial_number END serialNumber, tulink.user_name 'team.name', qhse.id, qhse.`status`, su.id 'inspectUserId', su.name 'name', qhse.create_time, qhse.number, mqcc.name as level_two_type_name, qhse.qhse_number FROM mes_building_qhse qhse left join contract_project cp on qhse.project_id = cp.id and cp.bool_delete_enum = 0 left join mes_building_workshop shop on qhse.workshop_id = shop.id and shop.bool_delete_enum = 0 left join mes_building_process pss on qhse.process_id = pss.id and pss.bool_delete_enum = 0 left join tech_artifact art on qhse.product_id = art.id and art.bool_delete_enum = 0 left join tech_assemble ass on qhse.product_id = ass.id and ass.bool_delete_enum = 0 left join mes_building_team_user_link tulink on qhse.team_id = tulink.team_id and tulink.bool_delete_enum = 0 and tulink.bool_leader_enum = 1 left join sys_user su on qhse.user_id = su.id and su.bool_delete_enum = 0 left join mes_quality_class_config mqcc ON mqcc.bool_delete_enum = 0 and mqcc.id = qhse.level_two_type where qhse.bool_delete_enum = 0 and qhse.type in (1,8)
and
qhse.team_id in
#{team.id}
and (art.structure_class_id in
#{classId}
or ass.assemble_config_id in
#{classId}
)
and DATE_FORMAT(qhse.create_time, '%Y-%m-%d %H') >= DATE_FORMAT(#{startDate}, '%Y-%m-%d %H')
and DATE_FORMAT(qhse.create_time, '%Y-%m-%d %H') <= DATE_FORMAT(#{endDate}, '%Y-%m-%d %H')
and qhse.project_id in
#{item}
and shop.id = #{workShopId}

SELECT tulink.user_name teamName, count(qhse.id) qhseQuantity FROM mes_building_qhse qhse inner join mes_building_team_user_link tulink on qhse.team_id = tulink.team_id and tulink.bool_delete_enum = 0 and tulink.bool_leader_enum = 1 WHERE qhse.bool_delete_enum = 0 AND qhse.type & 9
AND qhse.workshop_id = #{workShopId}
AND DATE_FORMAT( qhse.create_time, '%Y') = DATE_FORMAT(#{date},'%Y') GROUP BY tulink.user_name order by qhseQuantity Desc

SELECT cc.`name` levelOneTypeName, count(qhse.id) qhseQuantity FROM mes_building_qhse qhse left join mes_quality_class_config cc on qhse.level_one_type = cc.id and cc.bool_delete_enum = 0 WHERE qhse.bool_delete_enum = 0 AND qhse.type & 9
AND qhse.workshop_id = #{workShopId}
AND DATE_FORMAT( qhse.create_time, '%Y') = DATE_FORMAT(#{date},'%Y') GROUP BY cc.`name` order by qhseQuantity Desc

SELECT cp.serial_number serialNumber, cp.short_name shortName, qhse.qhse_number qhseNumber, case qhse.task_type_enum when 2 then ta.serial_number when 16 then ass.serial_number end productSerialNumber, ccone.`name` levelOneTypeName, cctwo.`name` levelTwoTypeName, tulink.user_name teamLeaderName, pro.`name` processName, su.`name` inspectUserName FROM mes_building_qhse qhse LEFT JOIN contract_project cp ON qhse.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN tech_artifact ta ON qhse.product_id = ta.id AND ta.bool_delete_enum = 0 AND qhse.task_type_enum = 2 LEFT JOIN tech_assemble ass ON qhse.product_id = ass.id AND ass.bool_delete_enum = 0 AND qhse.task_type_enum = 16 LEFT JOIN mes_building_process pro ON qhse.process_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN mes_building_team_user_link tulink ON qhse.team_id = tulink.team_id AND tulink.bool_leader_enum = 1 LEFT JOIN mes_quality_class_config ccone on qhse.level_one_type = ccone.id and ccone.bool_delete_enum = 0 LEFT JOIN mes_quality_class_config cctwo on qhse.level_two_type = cctwo.id and cctwo.bool_delete_enum = 0 left join sys_user su on qhse.user_id = su.id and su.bool_delete_enum = 0 WHERE qhse.bool_delete_enum = 0 AND qhse.type &9 and qhse.status not in (4, 64)
AND qhse.workshop_id = #{workShopId}
and DATE(qhse.create_time) = CURDATE()

SELECT cc.`name` levelOneName, count(*) quantity FROM mes_building_qhse qh LEFT JOIN mes_quality_class_config cc ON qh.level_one_type = cc.id and cc.bool_delete_enum = 0 where qh.bool_delete_enum = 0 and qh.type in (1,8)
and Year(qh.create_time) = #{year}
GROUP BY cc.`name`

SELECT DATE_FORMAT(qh.create_time,'%Y-%m') date, count(*) quantity FROM mes_building_qhse qh where qh.bool_delete_enum = 0
and Year(qh.create_time) = #{year}
GROUP BY DATE_FORMAT(qh.create_time,'%Y-%m')

SELECT DATE_FORMAT(qh.create_time,'%Y-%m') date, count(*) qhseQuantity FROM mes_building_qhse qh where qh.type &9
and Year(qh.create_time) = #{year}
GROUP BY DATE_FORMAT(qh.create_time,'%Y-%m');

SELECT su.`name` teamName, count(*) qhseQuantity FROM mes_building_qhse qh left join sys_user su on qh.duty_id = su.id and su.bool_delete_enum = 0 where qh.bool_delete_enum = 0 and qh.type &9
and Year(qh.create_time) = #{year}
GROUP BY su.`name`;

SELECT su.`name` teamName, count(*) inspectQuantity FROM mes_building_produce_inspection_team_report tr left join sys_user su on tr.user_id = su.id and su.bool_delete_enum = 0 where tr.bool_delete_enum = 0
and Year(tr.create_time) = #{year}
GROUP BY su.`name`;

SELECT su.`name` teamName, count(*) quantity FROM mes_building_qhse qh left join sys_user su on qh.duty_id = su.id and su.bool_delete_enum = 0 where qh.bool_delete_enum = 0 and qh.type & 9
and Year(qh.create_time) = #{year}
GROUP BY su.`name` ORDER BY count(*) DESC;

SELECT IFNULL(sum(IFNULL(qh.problem_quantity,1)),0) FROM mes_building_qhse qh WHERE qh.bool_delete_enum = 0 and qh.type in (1,8) and qh.task_type_enum = 2
and qh.workshop_id = #{workshopId}
and qh.team_id = #{teamId}
